"""Exigences d'identité, de partage et de contrôle des contacts."""


def appliquer_identite(ctx):
    root=ctx['ROOT'];write=ctx['write_doc'];load=ctx['load_sections'];put=ctx['put'];table=ctx['table'];glossary=ctx['GLOSSARY']
    formats=table(['Forme de partage','Comportement attendu','Internet / intranet'],[
        ('Lien de contact HTTPS','Ouvre une fiche de contact avec identité permanente, adresse et action de demande de conversation. URL stable basée sur l’identité ; nom lisible facultatif.','Domaine public pour l’édition en ligne ; domaine interne et certificat reconnu pour l’intranet.'),
        ('QR code','Encode le lien de contact ; lecture par caméra ou import d’une image. Export PNG et SVG, ainsi qu’une carte imprimable. Génération locale sans service QR tiers.','Un QR peut être lu sans Internet ; ouvrir son lien exige que le serveur cible soit accessible, au moins sur le réseau local.'),
        ('Copier adresse / identifiant / lien','Trois boutons distincts pour choisir la représentation utile. Le destinataire peut coller le résultat dans « Ajouter un contact ».','Disponible sur les deux éditions ; sélection manuelle proposée si le presse-papiers navigateur est indisponible.'),
        ('Partager via le système','Utilise la feuille de partage du téléphone ou du navigateur lorsque disponible : messagerie, courriel et autres applications installées.','Détection de capacité, contexte sécurisé et action explicite ; repli vers copie ou téléchargement. Pas de promesse identique sur tous les navigateurs.'),
        ('Carte de contact importable','Fichier JSON versionné proposé pour les humains et les agents : identité stable, libellé, adresses et informations publiques vérifiables. Format et signature à spécifier avant développement.','Transfert possible sur support local ; vérifier l’identité et la validité des adresses avant communication. Pas d’accès réseau automatique à l’import.'),
        ('URI Matrix compatible','Offrir un URI Matrix conforme, en complément du lien Polytalk, pour les clients compatibles.','Le client choisi doit pouvoir joindre le homeserver ; ce raccourci ne transporte pas toute la preuve d’identité Polytalk.'),
        ('Carte image / impression / signature','Carte lisible avec nom, type humain ou agent, adresse, QR et lien. Utilisable dans une signature de courriel ou un document.','L’image est partageable hors ligne ; elle ne masque pas les informations qu’elle affiche.'),
        ('NFC et partage à proximité','Pistes ultérieures : une puce NFC peut porter le même lien ; les mécanismes de proximité du système peuvent partager le fichier ou le lien.','Dépendent du matériel et du système ; hors périmètre du MVP, sans protocole radio propriétaire.')])
    identity=table(['Élément','Règle proposée','Statut'],[
        ('Identifiant permanent','UUIDv4 généré avec un générateur cryptographiquement sûr ; unicité contrôlée à l’enregistrement ; indépendant du libellé et de la clé courante.','Proposition technique à valider avant code.'),
        ('Partie choisie par l’utilisateur','Alias lisible disponible dans un domaine donné ; nom d’affichage séparé. Règles de caractères et noms réservés à arrêter.','Choix proposé à la suite de la discussion.'),
        ('Adresse Matrix','Utilisateur et domaine Matrix associés au compte ; le MXID n’est pas un alias librement renommable. Un changement de compte exige une procédure de migration.','Contrainte à intégrer à la conception.'),
        ('Identité de l’agent','Compte distinct par agent logique, avec installations et clés distinctes ; un redémarrage ne crée pas automatiquement une nouvelle identité.','Proposition ; rattachement obligatoire à un propriétaire encore à décider.'),
        ('Clés','Clés privées chez le client de confiance ; informations publiques partageables ; ne pas confondre authentification Polytalk et clés E2EE Matrix.','Orientation de sécurité déjà retenue.'),
        ('Humain ou agent','Le profil indique son type ; être marqué humain n’est pas une preuve de personne réelle. Aucun badge de vérification sans procédure définie.','Périmètre humain/agent confirmé ; vérification à concevoir.')])
    write('02-architecture/identite-et-partage.html','Polytalk — Identité et partage des contacts',[
        ('statut','Exigence confirmée et périmètre','<p>Le porteur demande de partager son identifiant par lien, QR code et autres formes modernes et pratiques. Cela concerne les humains et les agents IA, dans les éditions Internet et intranet. Le présent document spécifie des comportements à développer ; aucun générateur de QR ni mécanisme d’identité n’est encore implémenté.</p>'),
        ('identite','Séparer identité, adresse et présentation',identity+'<p>L’adresse lisible suggérée suit la forme <code>@alice:entreprise.example</code>. Cette adresse n’est pas la clé privée ni, à elle seule, une preuve cryptographique. Le lien de partage doit cibler une identité stable afin de limiter les erreurs après changement de libellé.</p><p>Clarification de la discussion : un alias Polytalk pourra évoluer selon notre politique, mais cela ne signifie pas qu’un identifiant de compte Matrix puisse être renommé sur place. La continuité entre serveurs exige une migration vérifiable, pas une simple modification de texte.</p>'),
        ('formats','Formats de partage prévus',formats),
        ('parcours','Parcours « Mon identifiant »','<ol><li>Ouvrir sa fiche : nom d’affichage, type de compte, adresse et identité permanente consultable.</li><li>Choisir « Copier mon lien », « Afficher mon QR », « Partager » ou « Exporter ma carte ».</li><li>Le destinataire scanne, colle ou importe ; Polytalk affiche une prévisualisation de l’identité et du serveur.</li><li>Le destinataire vérifie les informations publiques disponibles puis choisit d’ajouter le contact ou de demander une conversation.</li><li>La politique de réception du titulaire s’applique avant toute remise ou notification à l’agent.</li></ol><p>Un scan n’ajoute pas silencieusement un contact à la liste blanche, ne lance pas un agent et n’exécute jamais une commande. Une carte présentée par son propre signataire ne prouve pas seule l’identité réelle : les contacts sensibles exigent une vérification indépendante.</p>'),
        ('confidentialite','Données publiques et sécurité','<p>Ne partager que les données publiques nécessaires : identité permanente, adresse de contact, libellé choisi, version du format et éléments publics de vérification. Ne jamais inclure clé privée, mot de passe, jeton API, session de connexion ou clé de récupération dans un lien, un QR ou un export de contact.</p><p>Un QR est un encodage, pas un mécanisme de chiffrement ou de confiance. Le décodeur doit refuser les schémas d’URL dangereux, limiter taille et formats, afficher le domaine et ne jamais importer de clés privées. Aucun suivi analytique externe n’est nécessaire pour afficher ou générer une carte.</p><p>Un lien de profil n’est pas une invitation donnant des permissions. Si des invitations temporaires sont ajoutées, elles auront un objet et un traitement séparés. Révoquer un lien ne retire pas l’identifiant à quelqu’un qui l’a déjà copié ; le blocage et les permissions protègent la réception.</p>'),
        ('reception','Blocage et liste blanche','<p>Exigence issue du cadrage du développement : bloquer une adresse spécifique ou accepter uniquement les personnes figurant sur une liste blanche. Résoudre l’adresse vers une identité vérifiée avant d’appliquer la règle ; conserver le blocage malgré un changement de nom. Une nouvelle identité créée par la même personne nécessite des mesures supplémentaires contre le contournement ; le blocage ne prouve pas une identité réelle.</p><p>Ordre proposé : identité bloquée → refus ; sinon mode liste blanche → accepter seulement les identités autorisées ; sinon appliquer la politique de demandes de contact. Un blocage prime sur une autorisation. Les règles doivent aussi couvrir invitations et groupes ; la portée précise pour les groupes reste à spécifier.</p><p>Sur une infrastructure Matrix fédérée, ne pas promettre que toute donnée indésirable est arrêtée avant d’atteindre le serveur : qualifier séparément filtrage au serveur, adhésion aux salons et filtrage à la réception. Aucun événement rejeté ne doit être remis au modèle ou réveiller l’agent.</p>'),
        ('editions','Comportement Internet et intranet','<p>En ligne : lien sous le domaine de l’installation publique. Intranet : lien sous son domaine interne, résolution DNS et confiance TLS locales. Ne pas dépendre d’un raccourcisseur public ou d’un générateur QR externe. Fournir carte exportable et adresse textuelle comme alternatives.</p><p>Copier une carte d’un intranet isolé sur Internet ne crée aucune connectivité vers cet intranet. L’import permet de conserver un contact ; l’application indique lorsque sa destination est inaccessible. Les URI Matrix et liens Polytalk sont deux formes de résolution, pas une garantie de traversée des réseaux isolés.</p>'),
        ('priorites','Priorités de développement','<p><strong>MVP :</strong> lien, QR généré localement et exportable, copie d’adresse/lien/identifiant, import par texte ou image, prévisualisation et contrôle des permissions. Ajouter partage système avec repli et carte de contact JSON versionnée. La version initiale de la signature et de la migration d’identité doit être définie avant de revendiquer un export authentifié.</p><p><strong>Ensuite :</strong> carte imprimable enrichie, export vCard contenant un lien pour les carnets humains, NFC et fonctions de proximité. Une vCard ne doit pas être interprétée comme un format de preuve cryptographique Polytalk.</p>'),
        ('validation','Vérifications à prévoir','<ul><li>Deux comptes au même nom sur des domaines différents restent distincts.</li><li>QR exporté puis scanné : même identité que le lien et la carte ; aucune donnée secrète.</li><li>Intranet sans Internet : génération, copie et import restent disponibles ; résolution interne fonctionne.</li><li>Partage système indisponible : copie et téléchargement restent utilisables.</li><li>Adresse modifiée : le blocage et les permissions suivent l’identité, pas le seul libellé.</li><li>Carte altérée, signature invalide ou serveur différent : avertissement ou refus selon le profil défini ; aucune confiance silencieuse.</li><li>Expéditeur bloqué ou absent de la liste blanche : aucune remise au runtime.</li></ul><p>Ces tests restent à exécuter après implémentation.</p>'),
        ('glossaire','Glossaire',glossary+'<dl><dt>QR code</dt><dd>Code visuel contenant une donnée, ici principalement un lien de contact.</dd><dt>MXID</dt><dd>Identifiant utilisateur Matrix comprenant une partie locale et le nom du serveur.</dd><dt>Alias Polytalk</dt><dd>Nom lisible de présentation ou de recherche, distinct de l’identité permanente et du compte Matrix.</dd><dt>Carte de contact</dt><dd>Ensemble de données publiques pour découvrir et vérifier un correspondant ; distinct d’une invitation et d’un secret de connexion.</dd></dl>'),
        ('sources','Sources et statut','<ul><li><a href="https://spec.matrix.org/latest/appendices/">Spécification Matrix : identifiants, URI et navigation</a>.</li><li><a href="https://www.rfc-editor.org/rfc/rfc9562.html">IETF RFC 9562 : UUID</a>.</li><li><a href="https://developer.mozilla.org/en-US/docs/Web/API/Web_Share_API">MDN : Web Share API et conditions de disponibilité</a>.</li></ul><p>Revue documentaire du 16 octobre 2026. Les formats spécifiques Polytalk et les règles de produit ci-dessus sont des propositions, pas des fonctions garanties par Matrix. Le développement de l’application reste suspendu à la définition de l’identité, conformément à la demande du porteur.</p>')], '0.1')
    for rel,title in [
        ('00-pilotage/index.html','Polytalk — Registre documentaire'),
        ('01-cadrage/vision.html','Polytalk — Vision et besoins initiaux'),
        ('02-architecture/decisions.html','Polytalk — Orientations d’architecture et sécurité'),
        ('04-livrables/feuille-de-route-integration.html','Polytalk — Feuille de route d’intégration')]:
        items=load(rel)
        href='identite-et-partage.html' if rel.startswith('02-architecture/') else '../02-architecture/identite-et-partage.html'
        text='<p>Exigence confirmée : partager le contact humain ou agent par lien, QR code et autres formats pratiques. Prévoir copie d’adresse, partage système avec repli et carte importable, sans secret. Le scan ne modifie pas les permissions. Le blocage et le mode liste blanche restent applicables.</p><p><a href="'+href+'">Spécification identité et partage des contacts</a> : parcours, priorités, règles intranet et tests à prévoir. Le modèle d’identité détaillé demeure une proposition à stabiliser avant le code.</p>'
        items=put(items,('partage-identite','Identité et partage des contacts · Exigence enregistrée',text))
        write(rel,title,items,'0.5')
    archive='05-archives/2026-10-16-identite-partage.html'
    if not (root/archive).exists():
        write(archive,'Polytalk — Archive du cadrage de l’identité et du partage',[
            ('recueil','Éléments recueillis','<p>Le porteur demande de suspendre le développement pour définir la création des identifiants, examine le choix de leur partie lisible, puis exige le partage par lien, QR code et autres formats modernes. L’application concerne humains et agents ; blocage et liste blanche font partie des exigences exprimées.</p>'),
            ('statut','Statut de la réponse','<p>Spécification documentaire créée. Le modèle permanent/adresse/clés reste proposé ; la responsabilité des comptes agents et le profil de migration ne sont pas encore validés. Aucun code d’application ou partage effectif n’est annoncé.</p>'),
            ('glossaire','Glossaire',glossary)])
